messages.content:
Tool response:
Tool: create_fleet_lead
Description: Create Fleet Lead
Parameters:
    {
      "type": "object",
      "properties": {
        "company_name": {
          "type": "string",
          "title": "Company Name"
        },
        "contact_name": {
          "type": "string",
          "title": "Contact Name"
        },
        "contact_phone": {
          "type": "string",
          "title": "Contact Phone"
        },
        "contact_email": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Contact Email"
        },
        "source": {
          "type": "string",
          "title": "Source"
        },
        "assigned_to": {
          "type": "integer",
          "title": "Assigned To"
        },
        "vehicles": {
          "items": {
            "properties": {
              "make": {
                "type": "string",
                "title": "Make"
              },
              "model": {
                "type": "string",
                "title": "Model"
              },
              "model_year": {
                "type": "integer",
                "title": "Model Year"
              },
              "quantity": {
                "type": "integer",
                "title": "Quantity"
              },
              "notes": {
                "anyOf": [
                  {
                    "type": "string"
                  },
                  {
                    "type": "null"
                  }
                ],
                "title": "Notes"
              }
            },
            "type": "object",
            "required": [
              "make",
              "model",
              "model_year",
              "quantity"
            ],
            "title": "VehicleRequest"
          },
          "type": "array",
          "title": "Vehicles"
        }
      },
      "required": [
        "company_name",
        "contact_name",
        "contact_phone",
        "source",
        "assigned_to",
        "vehicles"
      ]
    }
